export type Era =
  | 'Ancient'
  | 'Medieval'
  | 'Colonial'
  | 'Pre-independence'
  | 'Early Republic'
  | 'Decimal India'
  | 'Modern India'
  | 'Digital Future';

export interface SecurityFeature {
  name: string;
  description: string;
  uvEffect?: string;
  coordinates?: { x: number; y: number }; // percentage position on obverse
}

export interface CurrencyItem {
  id: string;
  era: Era;
  type: 'Coin' | 'Note' | 'Digital';
  denomination: string;
  title: string;
  year: string;
  dateRange: string;
  issuer: string;
  material?: string;
  dimensions?: string;
  shape?: string;
  status: 'Historical artifact' | 'Demonetised' | 'Withdrawn' | 'Current legal tender' | 'Pilot phase';
  accent: string;
  obverseImage: string;
  reverseImage?: string;
  obverseDescription: string;
  reverseDescription?: string;
  historicalContext: string;
  purchasingPowerEquivalent: {
    year: number;
    equivalent: string;
    details: string;
  };
  securityFeatures?: SecurityFeature[];
  sources: string[];
}

export interface Source {
  id: string;
  label: string;
  url: string;
  note: string;
}

