    "historicalContext": "The iconic Five Rupees definitive coin was introduced in 1992 in solid cupro-nickel (9 grams). Due to rampant border smuggling where coins were melted down to manufacture razor blades, the Government of India and RBI re-issued the series in 2009 in a lighter 6-gram Nickel-Brass alloy, successfully safeguarding the currency's intrinsic vs nominal value.",
